package org.apache.commons.math.util;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.util.*;
import java.util.Arrays;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for MathUtils.gcd
 */
public class MathUtils_gcd_TriageGen2Test {













    @Test(expected = ArithmeticException.class)
    public void testGcdOverflowException() {
        // Forces k to reach 31
        // u and v must both be divisible by 2^31. 
        // Since 2^31 is out of range for positive int, we use the bit pattern.
        // However, the loop condition is (u & 1) == 0 && (v & 1) == 0.
        // The only way to hit k=31 is if both numbers are 0 (but that's handled by the first if)
        // or if we use Integer.MIN_VALUE which is -2^31.
        // If u = -2^31 and v = -2^31, the loop will run 31 times.
        MathUtils.gcd(Integer.MIN_VALUE, Integer.MIN_VALUE);
    }


}

